mapper.sql:
(
    (c.start_time is not null and c.start_time <= #{now}
        and (c.end_time > #{now}
            or (c.type = 1 and exists (
                select 1
                from supplement_contest sc
                inner join user_contest uc
                    on uc.contest_id = sc.contest_id and uc.user_id = sc.user_id
                where sc.contest_id = c.contest_id
                  and c.end_time is not null
                  and sc.deadline >= c.end_time
                  and sc.deadline > #{now}
            ))))
    or exists (
        select 1
        from contest_attempt pending_attempt
        where pending_attempt.contest_id = c.contest_id
          and pending_attempt.problem_id in

              #{problemId}

          and pending_attempt.state = 'PENDING'
    )
)

mapper.select:
select refs.contest_id from ( select c.contest_id from contest c inner join contest_problem_snapshot s on s.contest_id = c.contest_id where c.del_flag = 0 and s.problem_id in
#{problemId}
and union select c.contest_id from contest c inner join problem_problem_list ppl on ppl.list_id = c.list_id where c.del_flag = 0 and c.problem_snapshot_at is null and ppl.problem_id in
#{problemId}
and union select c.contest_id from contest_attempt a inner join contest c on c.contest_id = a.contest_id where c.del_flag = 0 and a.problem_id in
#{problemId}
and a.state = 'PENDING' ) refs order by refs.contest_id asc

select c.contest_id from contest c inner join contest_problem_snapshot s on s.contest_id = c.contest_id where c.del_flag = 0 and s.problem_id in
#{problemId}
and order by c.contest_id asc for share of s

select c.contest_id from contest c inner join problem_problem_list ppl on ppl.list_id = c.list_id where c.del_flag = 0 and c.problem_snapshot_at is null and ppl.problem_id in
#{problemId}
and order by c.contest_id asc for share of ppl

select c.contest_id from contest_attempt a inner join contest c on c.contest_id = a.contest_id where c.del_flag = 0 and a.problem_id in
#{problemId}
and a.state = 'PENDING' order by c.contest_id asc for share of a
